public class FridayCounter {

    public static int countFridays(java.time.LocalDate start, java.time.LocalDate end) {
        int count = 0;
        for (java.time.LocalDate d = start; !d.isAfter(end); d = d.plusDays(1)) {
            if (d.getDayOfWeek() == java.time.DayOfWeek.FRIDAY) {
                count++;
            }
        }
        return count;
    }
}
